    """Normalize a US phone number to the form (XXX) XXX-XXXX."""
    import re
    match = re.fullmatch(r"\d{3}-\d{3}-\d{4}""", s)
    if match:
        return f"({match.group(1)}) {match.group(2)}-{match.group(3)}"
    match = re.fullmatch(r"\(\d{3}\) \d{3} \d{4}""", s)
    if match:
        return f"{match.group(1)}-{match.group(2)}-{match.group(3)}"
    return s

